<?php
namespace Tests\Feature;use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use App\Models\{User,Role,Provider,ProviderCategory,ProviderMedia,ProviderApplication,ServiceCategory,Service};use Illuminate\Support\Facades\Hash;use Illuminate\Support\Str;
class AdminOverviewTest extends TestCase{use RefreshDatabase;private function user(string $role){$u=User::create(['name'=>$role.' User','phone'=>'+201'.random_int(100000000,999999999),'password_hash'=>Hash::make('Password1'),'status'=>'ACTIVE']);$u->roles()->attach(Role::firstOrCreate(['name'=>$role]));return $u;}protected function setUp():void{parent::setUp();$this->artisan('migrate');foreach(['REGISTERED_USER','PROVIDER','ADMIN','SUPER_ADMIN'] as $r)Role::firstOrCreate(['name'=>$r]);ProviderCategory::create(['name'=>'Trainer','status'=>'ACTIVE']);ServiceCategory::create(['name'=>'Training','status'=>'ACTIVE']);}
public function test_admin_dashboard_stats():void{$a=$this->user('ADMIN');$this->actingAs($a,'api')->getJson('/api/v1/admin/dashboard')->assertOk()->assertJsonStructure(['data'=>['users','providers','pending_applications','services','requests']]);}
public function test_users_are_paginated_with_roles_and_search():void{$a=$this->user('ADMIN');$u=$this->user('REGISTERED_USER');$this->actingAs($a,'api')->getJson('/api/v1/admin/users?search=REGISTERED')->assertOk()->assertJsonPath('data.data.0.phone',$u->phone)->assertJsonStructure(['data'=>['data'=>[['roles']]]]);}
public function test_verified_providers_include_media_count():void{$a=$this->user('ADMIN');$u=$this->user('PROVIDER');$p=Provider::create(['user_id'=>$u->id,'category_id'=>1,'bio'=>'Bio','location'=>'Cairo','verification_status'=>'VERIFIED','approved_at'=>now()]);ProviderMedia::create(['provider_id'=>$p->id,'type'=>'IMAGE','file_url'=>'https://example.com/a.jpg']);$this->actingAs($a,'api')->getJson('/api/v1/admin/providers')->assertOk()->assertJsonPath('data.data.0.media_count',1);}
public function test_non_admin_forbidden():void{$u=$this->user('REGISTERED_USER');$this->actingAs($u,'api')->getJson('/api/v1/admin/dashboard')->assertForbidden();}}
